function addQuestion() { if (!protect() || !ruleSource.value || !selection.value) return; try { apply({ type: 'ADD', docId: selection.value.docId, anchor: selection.value, values: { nameZh: t('新问题', 'New question'), nameEn: 'New question', type: { kind: 'boolean', zh: '是／否', en: 'Yes / No' }, role: { kind: 'input', zh: '项目资料', en: 'Project information' } }, reason: '人工从原文补充 / Added from the source' }); selectedId.value = state.value.variables.at(-1)!.id; resetForm() } catch (caught) { error.value = String(caught) } }
