  if (!protect()) throw Error(error.value)
  if (invalidTemplateSources.value.length) throw Error(t('模板缺少当前有效来源证据。请先在来源步骤替换或重新上传，再建立核对版本。', 'Templates need current bound source evidence. Replace or re-upload them in Sources before preparing a review.'))
  if (!rebuild && (head.value.draft ?? head.value.current)?.sourceStale) throw Error(t('当前核对版本引用的是旧来源证据。请按现有原件新建核对版本；历史记录继续保留。', 'This review references old source evidence. Start a new review from current sources; history is retained.'))
  if (!rebuild && state.value.variables.length) { if (dirty.value || !head.value.draft) return await save(); return head.value.draft }
  if (dirty.value) throw Error(t('先保存现有模板核对草稿，避免覆盖。', 'Save the current review before rebuilding candidates.'))
  busy.value = true; const project = props.projectId, token = generation
  try { const result = await draftingApi.reviewBootstrap(project); if (!alive || project !== props.projectId || token !== generation) return; graph.value = result.graph; head.value = { ...head.value, sources: [...head.value.sources.filter(source => !result.sources.some(item => String(item.id) === String(source.id))), ...result.sources] }; selectedId.value = ''; formOpen.value = false; changed(); busy.value = false; return await save() } finally { if (token === generation) busy.value = false }
}
async function confirm() { if (head.value.draft?.sourceStale || invalidTemplateSources.value.length || splitDirty.value || props.locked || dirty.value || formDirty.value || pending.value || !state.value.variables.some(item => item.status !== 'excluded') || !head.value.draftRevisionId) return; const project = props.projectId, token = generation; busy.value = true; try { await draftingApi.reviewConfirm(project, head.value.draftRevisionId, head.value.currentRevisionId); if (!alive || project !== props.projectId || token !== generation) return; await refresh(); emit('confirmed') } catch (caught) { error.value = caught instanceof Error ? caught.message : String(caught) } finally { if (project === props.projectId) busy.value = false } }
async function openHistory() { historyOpen.value = true; const project = props.projectId, token = generation; try { const incoming = await draftingApi.reviewRevisions(project); if (alive && project === props.projectId && token === generation) history.value = incoming } catch (caught) { if (project === props.projectId && token === generation) error.value = String(caught) } }
async function restoreRevision(revision: ReviewRevisionSummary) {
  if (busy.value || props.locked || !protect() || dirty.value) { error.value = t('请先保存当前草稿和候选调整。', 'Save the current draft and candidate edits first.'); return }
  const project = props.projectId, token = generation; busy.value = true
  try {
    const detail = await draftingApi.reviewRevision(project, revision.id)
    if (!alive || project !== props.projectId || token !== generation) return
    if (detail.id !== revision.id || detail.sourceStale || detail.graph?.kind !== 'consense-template-graph-v1') throw Error(t('此历史版本的来源已变化或内容不完整，不能恢复为当前草稿。', 'The historical source changed or its graph is incomplete. It cannot be restored as the current draft.'))
    graph.value = copy(detail.graph); changed(); selectedId.value = ''; formOpen.value = false; historyOpen.value = false
  } catch (caught) { if (project === props.projectId && token === generation) error.value = caught instanceof Error ? caught.message : String(caught) }
  finally { if (project === props.projectId && token === generation) busy.value = false }
}
async function openOriginal() { if (!reading.value) return; originalOpen.value = true; if (pdfUrl.value) URL.revokeObjectURL(pdfUrl.value); pdfUrl.value = ''; const project = props.projectId, source = reading.value, token = sourceGeneration; try { const blob = source.format === 'docx' ? await draftingApi.reviewPreview(project, String(source.id), source.sourceSha256) : await draftingApi.reviewSource(project, String(source.id), source.sourceSha256); if (!alive || project !== props.projectId || token !== sourceGeneration) return; pdfUrl.value = URL.createObjectURL(blob) } catch (caught) { if (!alive || project !== props.projectId || token !== sourceGeneration) return; error.value = caught instanceof Error ? caught.message : String(caught) } }
watch(() => props.projectId, (_project, previous) => { if (previous) snapshot(previous); sourceGeneration++; if (pdfUrl.value) URL.revokeObjectURL(pdfUrl.value); pdfUrl.value = ''; originalOpen.value = false; historyOpen.value = false; showGraph.value = false; cancelSplit(); reading.value = undefined; selection.value = undefined; dirty.value = false; formOpen.value = false; loading = refresh() }, { immediate: true })
watch(showGraph, open => { if (open) { graphSelected.value = selectedId.value; graphOnlySelected.value = false } })
watch([dirty, formDirty, splitDirty], () => emit('dirty', dirty.value || formDirty.value || splitDirty.value))
onBeforeUnmount(() => { snapshot(); if (captureFrame !== undefined) window.cancelAnimationFrame?.(captureFrame); alive = false; generation++; sourceGeneration++; if (pdfUrl.value) URL.revokeObjectURL(pdfUrl.value) })
defineExpose({ prepareCandidates, refresh, save, selectSource, locateSource, ready: () => loading, currentRevisionId: () => head.value.currentRevisionId })
</script>

<template>
  <section class="source-review" data-source-review><fieldset class="review-controls" data-review-controls :disabled="busy">
    <header class="review-heading"><div><h3>{{ t('在原件上核对规则', 'Review rules on the source') }}</h3><p>{{ t('模板规则确认与本项目事实采用分别保存。未知范围仍需核对。', 'Template confirmation and project-fact adoption are separate. Unresolved scope stays under review.') }}</p></div><div class="review-actions"><button class="btn" :disabled="busy" @click="openHistory">{{ t('图谱版本', 'Graph versions') }}</button><button class="btn" @click="showGraph = true">{{ t('查看关系', 'View relationships') }}</button><button class="btn" :disabled="busy || !undo.length || formDirty" @click="graph = { ...graph, graph: undo.pop()! }; changed(); resetForm()">{{ t('撤销', 'Undo') }}</button><button class="btn primary" data-review-save :disabled="busy || locked || !dirty || formDirty || splitDirty" @click="save">{{ t('保存核对草稿', 'Save review draft') }}</button><button class="btn" data-review-confirm :disabled="busy || locked || dirty || formDirty || splitDirty || pending > 0 || !state.variables.length || !head.draftRevisionId || head.draft?.sourceStale || invalidTemplateSources.length > 0" @click="confirm">{{ t('确认此版模板用于起草', 'Confirm this template for drafting') }}</button></div></header>
    <p v-if="busy" role="status">{{ t('正在读取或保存…', 'Reading or saving…') }}</p><p v-if="error" class="review-error" role="alert">{{ error }}</p><p class="review-status">{{ state.variables.length }} {{ t('项记录', 'records') }} · {{ pending }} {{ t('项未确认', 'unconfirmed') }} · {{ dirty || formDirty || splitDirty ? t('有未保存调整', 'Unsaved changes') : t('草稿与确认版本分别保留', 'Draft and confirmed revisions are kept separately') }}</p>
    <div class="source-choice"><label>{{ t('原件', 'Source') }}<select :value="sourceId" :disabled="busy || formDirty" @change="selectSource(($event.target as HTMLSelectElement).value)"><option v-for="source in head.sources" :key="source.id" :value="String(source.id)">{{ source.fileName }} · {{ source.format }} · {{ source.parseStatus }}</option></select></label><button class="btn" :disabled="!reading" @click="openOriginal">{{ t('查看原件版面', 'View original layout') }}</button><label v-for="family in ['NTT','SCT','SCC']" :key="family">{{ family }}<select v-model="graph.selectedDocuments[family]" :disabled="busy" @change="changed"><option value="">{{ t('未选择', 'Not selected') }}</option><option v-for="source in head.sources.filter(item => item.fileKey === family)" :key="source.id" :value="String(source.id)">{{ source.fileName }} · {{ source.format }}</option></select></label></div>
    <p v-if="(head.draft ?? head.current)?.sourceStale" class="review-error" data-source-review-stale role="status">{{ t('此核对版本引用了旧来源证据。请返回“识别”并按现有原件新建核对版本；保存的历史记录保留。', 'This review references old source evidence. Return to Identify and start a new review from current sources. Saved history is retained.') }}</p>
    <p v-if="selectedSource" class="review-status" data-source-evidence-status role="status">{{ sourceEvidenceLabel(selectedSource) }} · {{ t('分析代次', 'Analysis revision') }}: {{ selectedSource.analysisRevision || t('未提供', 'Not provided') }}</p>
    <div v-if="invalidTemplateSources.length" class="review-error" data-source-evidence-block role="alert"><p>{{ t('这些模板没有当前有效的来源证据；原件未变化也可能是分析代次已过期。请先替换或重新上传，再建立并核对新版本。', 'These templates lack current bound evidence. An unchanged original can still have an expired analysis revision. Replace or re-upload them, then prepare and review a new version.') }}</p><ul><li v-for="source in invalidTemplateSources" :key="source.id">{{ source.fileKey }} · {{ source.fileName }} · {{ sourceEvidenceLabel(source) }}</li></ul><button type="button" class="btn" data-source-replace @click="emit('replace')">{{ t('到来源步骤替换／重传', 'Replace or re-upload in Sources') }}</button></div>
    <p v-if="selectedSource?.format === 'pdf'" class="source-note" data-source-pdf-limit>{{ t('这份 PDF 可阅读和核对来源；生成保留原格式的 Word 需要所选版次的可编辑 DOCX，不能借另一版 Word。', 'This PDF supports source reading and review. Word generation needs an editable DOCX of the selected edition; another Word edition cannot be substituted.') }}</p>
    <details><summary>{{ t('原件核对的六个问题', 'Six questions for source review') }}</summary><p>{{ t('要求处理什么；怎么回答；属于哪条明细；前提和共同条件；结果怎样得出；改哪段、怎样改。', 'What is required; answer shape; detail ownership; prerequisites and combined conditions; how the result is obtained; which passage changes and how.') }}</p></details>
    <p v-if="state.discoverySummary" class="review-status">{{ t('本次模板识别', 'This template discovery run') }} · {{ t('已尝试', 'Attempted') }} {{ state.discoverySummary.attempted }} · {{ t('成功返回', 'Returned') }} {{ state.discoverySummary.succeeded }} · {{ t('失败', 'Failed') }} {{ state.discoverySummary.failed }} · {{ t('预算外未执行', 'Outside budget') }} {{ state.discoverySummary.skippedBudget }}. {{ t('再次点击只识别尚未尝试的要求；失败记录保留，不会自动重试。', 'A later run processes unattempted requirements. Failures remain recorded and are not retried automatically.') }}</p>
    <details v-if="state.events.length"><summary>{{ t('核对与识别记录', 'Review and discovery records') }}</summary><article v-for="(event,index) in state.events" :key="index"><p>{{ event.zh }} / {{ event.en }}</p><p class="source-note">{{ event.time ?? event.at }}</p><p v-for="(detail,detailIndex) in event.details ?? []" :key="detailIndex">{{ detail }}</p><details v-if="event.data?.rawResponse || event.data?.reason"><summary>{{ t('本次识别的原始结果／失败', 'Raw discovery result or failure') }}</summary><pre>{{ event.data.rawResponse }}</pre><p>{{ event.data.reason }}</p></details></article></details>
    <div v-if="reading" class="review-columns">
      <section ref="sourceHost" class="native-source" @mouseup="scheduleCapture" @dblclick="scheduleCapture" @keyup="scheduleCapture"><p class="source-note">{{ t('Word文字来自本份原件的可编辑通道。可拖选跨段的准确文字，或把多段独立选区逐项追加到同一修改位置；不把原生段落当作物理页码。', 'Word text is the editable channel of this source. Select exact text across paragraphs, or append separate selections to one target. Paragraph order is not a physical page number.') }}</p><details v-if="reading.guidanceNotes?.length"><summary>{{ t('原件识别的指导要求', 'Recognized source guidance') }} · {{ reading.guidanceNotes.length }}</summary><blockquote v-for="note in reading.guidanceNotes" :key="note.id">{{ note.text }}<small>{{ note.captureComplete ? t('原文捕获完整', 'Source capture complete') : t('原文范围未完整确认', 'Source capture incomplete') }} · {{ note.sourceSyntaxComplete === true ? t('原文语法闭合；适用性仍待核', 'Source syntax complete; applicability still needs review') : note.sourceSyntaxKnown === true ? t('原文语法未闭合；需核对源文', 'Source syntax incomplete; check the original') : t('原文语法尚未获来源确认', 'Source syntax remains unverified') }}</small></blockquote></details><details v-if="reading.markerCandidates?.some(marker => marker.disposition === 'unknown') || reading.issues?.length" data-source-unresolved><summary>{{ t('原件待核对事项：不授权自动编辑', 'Source issues requiring review; no automatic edit authority') }}</summary><p>{{ t('符号捕获、范围完整、原文语法和项目适用性分别判断；未知符号和未闭合原文需人工确认。', 'Marker capture, complete scope, source syntax and project applicability are separate. Unknown markers and incomplete source syntax need human review.') }}</p><pre>{{ JSON.stringify({ markers: reading.markerCandidates?.filter(marker => marker.disposition === 'unknown'), issues: reading.issues }, null, 2) }}</pre></details><article v-for="paragraph in reading.paragraphs" :key="paragraph.id" class="native-paragraph"><span class="paragraph-number">{{ paragraph.ordinal }}</span><p :data-native-id="paragraph.id">{{ paragraph.text }}</p></article><p v-if="!reading.paragraphs?.length">{{ t('本来源未提供可编辑Word段落；请查看实际原件及保留的观察材料。不能借另一版Word执行修改。', 'This source has no editable Word paragraphs. Review its original and retained observations; another Word edition cannot authorize edits.') }}</p><details v-for="(block, index) in reading.blocks ?? []" :key="block.id ?? index"><summary>{{ t('来源观察', 'Source observation') }} {{ index + 1 }}</summary><pre :data-block-id="block.id ?? block.blockId">{{ block.originalText ?? block.text ?? block.effectiveText }}</pre></details></section>
      <aside class="review-editor"><div v-if="selection" class="selection-tools"><blockquote>{{ selection.text }}</blockquote><div class="review-actions"><button class="btn" :disabled="!ruleSource" @click="addQuestion">{{ t('从选词补充问题', 'Add a question from selection') }}</button><button class="btn" :disabled="!selected || !ruleSource" @click="linkSource">{{ t('关联当前问题', 'Link current question') }}</button><button class="btn" :disabled="!selected || !ruleSource || !selection.native" @click="addTarget">{{ t('作为修改目标', 'Use as amendment target') }}</button></div></div>
        <input v-model="search" class="question-search" :placeholder="t('搜索问题', 'Search questions')"><select data-review-question-select :value="selectedId" :disabled="formDirty" @change="choose(($event.target as HTMLSelectElement).value)"><option value="">{{ t('选择一个问题核对', 'Choose a question') }}</option><option v-for="item in filtered" :key="item.id" :value="item.id">{{ item.nameZh }} / {{ item.nameEn }} · {{ item.status }}</option></select>
        <div v-if="isolatedRule && formOpen" class="source-note"><p>{{ t('问题及原文已保留，无法确认的规则已隔离。可移除此空规则，保留问题供人工核对；不会增加修改目标或采用项目答案。', 'The question and source are retained; the unresolved rule is isolated. Remove this empty rule to review the question manually. This adds no amendment targets or adopted project answers.') }}</p><button class="btn" data-review-remove-isolated-rule :disabled="busy || formDirty" @click="removeIsolatedRule">{{ t('移除隔离规则，保留问题', 'Remove isolated rule and retain question') }}</button></div>
        <template v-if="selected && formOpen"><div class="review-actions"><button class="btn" data-review-confirm-item :disabled="formDirty" @click="reviewItem">{{ t('该项已核对', 'Mark this item reviewed') }}</button><button class="btn" :disabled="formDirty" @click="splitOpen = true">{{ t('拆为两个问题', 'Split into two questions') }}</button><button class="btn" :disabled="formDirty" @click="apply({type: selected.status === 'excluded' ? 'RESTORE' : 'EXCLUDE', id: selectedId, reason: '人工核对 / Human review'}); resetForm()">{{ selected.status === 'excluded' ? t('恢复', 'Restore') : t('不再提问', 'Exclude') }}</button></div><label v-if="selected.correction?.kind === 'split'">{{ t('拆分后的关系', 'Relationship after splitting') }}<select v-model="form.splitMode"><option value="unknown">{{ t('待核对', 'Needs review') }}</option><option value="all">{{ t('两项同时成立', 'Both hold') }}</option><option value="any">{{ t('任一项成立', 'Either holds') }}</option></select></label><label>{{ t('中文问题', 'Chinese question') }}<input v-model="form.nameZh" data-review-name-zh></label><label>{{ t('英文问题', 'English question') }}<input v-model="form.nameEn" data-review-name-en></label><label>{{ t('怎么回答？', 'Answer shape') }}<select v-model="form.kind"><option v-for="(label, key) in kinds" :key="key" :value="key">{{ label }}</option></select></label><label>{{ t('答案怎样得出？', 'How is the answer obtained?') }}<select v-model="form.role"><option v-for="(label, key) in roles" :key="key" :value="key">{{ label }}</option></select></label><label>{{ t('属于哪条资料／明细？', 'Which record or list owns it?') }}<select v-model="form.parentId"><option value="">{{ t('独立项目资料', 'Project level') }}</option><option v-for="item in parents" :key="item.id" :value="item.id">{{ item.nameZh }} / {{ item.nameEn }}</option></select></label><label v-if="['choice','multiselect'].includes(form.kind)">{{ t('选项：每行中文 | English', 'Options: Chinese | English, one per line') }}<textarea v-model="form.optionsText" rows="4" /></label><label v-if="form.role === 'fixed'">{{ t('固定内容', 'Fixed wording') }}<textarea v-model="form.fixedValue" rows="3" /></label>
          <details><summary>{{ t('先满足什么、哪些条件共同决定？', 'Prerequisites and combined conditions') }}</summary><article v-for="(branch, branchIndex) in form.branches" :key="branch.id" class="condition-case"><label>{{ t('本情况', 'Case') }} {{ branchIndex + 1 }}<select v-model="branch.mode"><option value="all">{{ t('同时满足', 'All conditions') }}</option><option value="any">{{ t('任一满足', 'Any condition') }}</option></select></label><label>{{ t('按哪组明细逐项判断？', 'Evaluate within which list?') }}<select v-model="branch.scopeId" @change="branch.scopeMode = branch.scopeId ? 'each' : ''"><option value="">{{ t('整个项目', 'Whole project') }}</option><option v-for="item in parents.filter(value => value.type.kind === 'list')" :key="item.id" :value="item.id">{{ item.nameZh }}</option></select></label><select v-if="branch.scopeId" v-model="branch.scopeMode"><option value="each">{{ t('逐项分别判断', 'Evaluate each row') }}</option><option value="any">{{ t('任一条满足', 'Any row matches') }}</option><option value="all">{{ t('所有条均满足', 'All rows match') }}</option><option value="none">{{ t('没有条目满足', 'No rows match') }}</option></select><div v-for="(clause, index) in branch.clauses" :key="index" class="condition-row"><select v-model="clause.inputId" @change="clause.operator = allowedOperators(clause.inputId)[0]; clause.value = ''"><option value="">{{ t('选择输入', 'Choose input') }}</option><option v-for="item in state.variables.filter(value => value.status !== 'excluded')" :key="item.id" :value="item.id">{{ item.nameZh }} / {{ item.nameEn }}</option></select><select v-model="clause.operator"><option v-for="operator in allowedOperators(clause.inputId)" :key="operator" :value="operator">{{ operators[operator] }}</option></select><select v-if="optionInput(clause.inputId).length" v-model="clause.value"><option v-for="option in optionInput(clause.inputId)" :key="option.value" :value="option.value">{{ option.labelZh }} / {{ option.labelEn }}</option></select><input v-else-if="['eq','ge','le','gt','lt'].includes(clause.operator)" v-model="clause.value"><button class="btn" @click="branch.clauses.splice(index,1)">×</button></div><button class="btn" @click="branch.clauses.push({inputId:'',operator:'known',value:''})">{{ t('增加条件', 'Add condition') }}</button><label>{{ t('这种情况怎样处理？（中文）', 'Amendment for this case (Chinese)') }}<textarea v-model="branch.effectZh" /></label><label>{{ t('同一处理说明（英文）', 'Amendment for this case (English)') }}<textarea v-model="branch.effectEn" /></label><label v-if="form.role === 'derived'">{{ t('本情况的答案', 'Answer for this case') }}<select v-if="form.kind === 'boolean'" v-model="branch.resultValue"><option :value="true">{{ t('是', 'Yes') }}</option><option :value="false">{{ t('否', 'No') }}</option></select><select v-else-if="form.kind === 'choice'" v-model="branch.resultValue"><option v-for="option in options()" :key="option.value" :value="option.value">{{ option.labelZh }} / {{ option.labelEn }}</option></select><input v-else v-model="branch.resultValue"></label><button class="btn" @click="form.branches.splice(branchIndex,1)">{{ t('移除此情况', 'Remove case') }}</button></article><button class="btn" @click="addBranch">{{ t('增加一种情况', 'Add a case') }}</button></details>
          <details><summary>{{ t('改哪段、怎样改？', 'Which passage changes, and how?') }}</summary><article v-for="(target, index) in form.targets" :key="index" class="target-row"><blockquote>{{ target.text }}</blockquote><p v-if="target.nativeBinding && target.nativeBinding.status !== 'bound'" class="review-error">{{ target.nativeBinding.reason }}</p><select v-model="target.action" :data-target-action="index"><option v-for="(label, action) in actions" :key="action" :value="action" :disabled="action === 'insert' && !(targetSpans(target).length === 1 && targetSpans(target)[0]?.operation === 'insert')">{{ label }}</option></select><label>{{ t('适用于哪种情况？', 'Which case applies?') }}<select v-model="target.branchId"><option value="">{{ t('无条件', 'Unconditional') }}</option><option v-for="(branch, i) in form.branches" :key="branch.id" :value="branch.id">{{ i + 1 }} · {{ branch.effectZh }}</option></select></label><fieldset v-if="targetScope(target)" class="item-target"><legend>{{ t('这段原文对应哪一条明细？', 'Which list item does this source passage belong to?') }}</legend><label>{{ t('明细标记（若已知）', 'Item marker (if known)') }}<input v-model="target.itemId" placeholder="Item marker"></label><template v-if="!target.itemId"><label>{{ t('或按这项资料寻找同一条明细', 'Or match this detail within the same item') }}<select v-model="target.itemKey"><option value="">{{ t('选择识别资料', 'Choose identifying detail') }}</option><option v-for="key in itemKeys(target)" :key="key.id" :value="key.id">{{ key.nameZh }} / {{ key.nameEn }}</option></select></label><label v-if="target.itemKey">{{ t('这一条明细的准确值', 'Exact value for this item') }}<select v-if="state.variables.find(item => item.id === target.itemKey)?.type.kind === 'boolean'" v-model="target.itemValue"><option :value="true">{{ t('是', 'Yes') }}</option><option :value="false">{{ t('否', 'No') }}</option></select><select v-else-if="optionInput(target.itemKey).length" v-model="target.itemValue"><option v-for="option in optionInput(target.itemKey)" :key="option.value" :value="option.value">{{ option.labelZh }} / {{ option.labelEn }}</option></select><input v-else v-model="target.itemValue"></label></template><p class="source-note">{{ t('必须能唯一对应一条明细；其他条目的答案不会用于此段原文。', 'The match must identify one item. Answers from other items do not apply to this passage.') }}</p></fieldset><label v-if="['fill','replace'].includes(target.action) && targetSpans(target).length > 1">{{ t('新文字放在哪个选区？其余已选区将清空。', 'Which span receives the new text? Other selected spans will be cleared.') }}<select :value="target.replacementPlacement?.spanIndex ?? ''" :data-target-placement="index" @change="target.replacementPlacement = ($event.target as HTMLSelectElement).value === '' ? undefined : { spanIndex: Number(($event.target as HTMLSelectElement).value) }"><option value="">{{ t('请明确选择', 'Choose explicitly') }}</option><option v-for="(span,spanIndex) in targetSpans(target)" :key="spanIndex" :value="spanIndex">{{ spanIndex + 1 }} · {{ span.expectedText }}</option></select></label><p v-if="target.action === 'insert'" class="source-note">{{ t('只在来源指定的插入点增加文字；清单条数和内容需明确采用项目资料。', 'Insert only at the source anchor. List size and contents require explicit adoption of project facts.') }}</p><template v-if="['fill','replace','insert'].includes(target.action)"><label>{{ t('文字来自哪个答案？', 'Which answer supplies the text?') }}<select v-model="target.valueSourceId"><option value="">{{ t('固定替换文字', 'Fixed replacement') }}</option><option v-for="item in state.variables.filter(value => value.status !== 'excluded')" :key="item.id" :value="item.id">{{ item.nameZh }} / {{ item.nameEn }}</option></select></label><template v-if="target.valueSourceId"><select v-model="target.valueMode"><option value="single">{{ t('一个答案', 'One answer') }}</option><option value="join">{{ t('串联逐项答案', 'Join item answers') }}</option></select><template v-if="target.valueMode === 'join'"><select v-model="target.listId"><option v-for="item in parents.filter(value => value.type.kind === 'list')" :key="item.id" :value="item.id">{{ item.nameZh }}</option></select><label>{{ t('分隔文字', 'Exact separator') }}<input v-model="target.separator"></label></template><label>{{ t('答案前文字', 'Exact prefix') }}<textarea v-model="target.prefix" /></label><label>{{ t('答案后文字', 'Exact suffix') }}<textarea v-model="target.suffix" /></label></template><template v-else><label>{{ t('固定文字（中文）', 'Fixed wording (Chinese)') }}<textarea v-model="target.replacementZh" /></label><label>{{ t('固定文字（英文）', 'Fixed wording (English)') }}<textarea v-model="target.replacementEn" /></label></template></template><button class="btn" :disabled="!selection?.native || busy || target.action === 'insert'" :data-target-append="index" @click="appendTarget(index)">{{ t('把当前选区追加到此修改位置', 'Append current selection to this amendment target') }}</button><ol v-if="targetSpans(target).length > 1"><li v-for="(span,spanIndex) in targetSpans(target)" :key="spanIndex"><blockquote>{{ span.expectedText }}</blockquote></li></ol><button class="btn" @click="form.targets.splice(index,1)">{{ t('移除此目标', 'Remove target') }}</button></article><p class="source-note">{{ t('先在左边选词，再点“作为修改目标”。跨段目标分别保留，不扩成首尾整段。', 'Select words on the left and use them as an amendment target. Multiple spans remain distinct.') }}</p></details>
          <details><summary>{{ t('合并同一问题', 'Merge duplicate questions') }}</summary><select v-model="mergeId"><option value="">{{ t('选择保留的问题', 'Choose the retained question') }}</option><option v-for="item in state.variables.filter(value => value.id !== selectedId && value.status !== 'excluded')" :key="item.id" :value="item.id">{{ item.nameZh }} / {{ item.nameEn }}</option></select><button class="btn" :disabled="formDirty || !mergeId" @click="merge">{{ t('确认合并', 'Merge after review') }}</button></details><details><summary>{{ t('已关联原文', 'Linked source passages') }}</summary><article v-for="(anchor,index) in selected.sourceAnchors" :key="index"><blockquote>{{ anchor.text }}</blockquote><button class="btn" :disabled="formDirty" @click="apply({type:'UNLINK',id:selectedId,index}); resetForm()">{{ t('移除错误关联', 'Remove incorrect link') }}</button></article></details><footer class="review-actions"><button class="btn" @click="resetForm()">{{ t('取消当前调整', 'Cancel edit') }}</button><button class="btn primary" data-review-save-form :disabled="!formDirty" @click="saveForm">{{ t('记录问题调整', 'Keep question changes') }}</button></footer>
        </template>
      </aside>
    </div>
    <AppModal :open="splitOpen" :title="t('分别选取两个问题的原文', 'Select the source for each question')" wide @close="splitOpen = false"><p>{{ t('可先收起此窗在左侧选词，再打开保留选区。拆分不会复制旧项目答案。', 'Select each exact source passage. Splitting does not copy an adopted project answer.') }}</p><div class="split-columns"><section><button class="btn" :disabled="!selection" @click="splitFirst = selection">{{ t('当前选词作为第一项', 'Use selection for the first item') }}</button><blockquote>{{ splitFirst?.text }}</blockquote><input v-model="splitNames.firstZh" placeholder="中文名称"><input v-model="splitNames.firstEn" placeholder="English name"></section><section><button class="btn" :disabled="!selection" @click="splitSecond = selection">{{ t('当前选词作为第二项', 'Use selection for the second item') }}</button><blockquote>{{ splitSecond?.text }}</blockquote><input v-model="splitNames.secondZh" placeholder="中文名称"><input v-model="splitNames.secondEn" placeholder="English name"></section></div><select v-model="splitNames.mode"><option value="unknown">{{ t('关系仍待核对', 'Relationship to review') }}</option><option value="all">{{ t('两项同时成立', 'Both must hold') }}</option><option value="any">{{ t('任一项成立', 'Either may hold') }}</option></select><button class="btn" @click="cancelSplit">{{ t('取消本次拆分', 'Cancel this split') }}</button><button class="btn primary" @click="split">{{ t('保留两个独立问题', 'Keep two independent questions') }}</button></AppModal>
    <AppModal :open="showGraph" :title="t('问题、修改方案与原文文件', 'Questions, amendments and source files')" wide @close="showGraph = false">
      <div class="review-actions"><button class="btn" data-review-graph-clear @click="graphSelected=''; graphOnlySelected=false">{{ t('完整图谱／清除选中', 'Complete graph / clear selection') }}</button><button class="btn" data-review-graph-only :disabled="!graphSelected" :aria-pressed="graphOnlySelected" @click="graphOnlySelected=!graphOnlySelected">{{ graphOnlySelected ? t('显示完整图谱', 'Show complete graph') : t('只看选中链路', 'Show selected chain only') }}</button><span class="source-note">{{ t('选中链路与可能影响高亮，其他项目仍可选择。实际方案以已采用事实为准。', 'The selected chain and possible impact are highlighted. Other items remain selectable. Adopted facts determine the actual plan.') }}</span></div>
      <div v-if="graphLayout" class="review-graph-body"><div class="graph-scroll"><div class="graph-canvas" :style="{width:graphLayout.width+'px',height:graphLayout.height+'px'}"><svg :width="graphLayout.width" :height="graphLayout.height"><path v-for="edge in shownGraphEdges" :key="edge.id" :data-review-graph-edge="edge.id" :d="edge.path" class="graph-edge" :class="[edge.kind, {selected:graphImpact?.edgeIds.includes(edge.id),dim:graphSelected && !graphImpact?.edgeIds.includes(edge.id)}]" /></svg><button v-for="item in shownGraphItems" :key="item.id" :data-review-graph-node="item.id" class="graph-node" :class="[{selected:graphChain.has(item.id),dim:graphSelected && !graphChain.has(item.id)},item.id.startsWith('action:')?'action-node':item.docId?'file-node':'input-node']" :aria-pressed="graphSelected===item.id" :style="{left:item.x+'px',top:item.y+'px',width:item.w+'px',height:item.h+'px'}" @click="graphSelected=item.id"><strong>{{ graphLabel(item) }}</strong><small>{{ item.id.startsWith('action:') ? t('修改方案', 'Amendment action') : item.docId ? t('原文文件', 'Source file') : t('问题／资料', 'Question or detail') }}</small><small v-if="item.summaryZh || item.summaryEn">{{ locale==='en'?item.summaryEn:item.summaryZh }}</small></button></div></div>
      <aside class="review-graph-inspector"><template v-if="graphInspection"><h3>{{ graphLabel(graphInspection) }}</h3><p class="source-note">{{ t('前提关联', 'Upstream dependencies') }} {{ graphImpact?.upstreamIds?.length ?? 0 }} · {{ t('可能受影响的问题', 'Potentially affected questions') }} {{ graphImpact?.downstreamIds?.length ?? 0 }}</p><button class="btn" data-review-graph-locate :disabled="busy || formDirty" @click="locateGraphSelection">{{ graphInspection.docId ? t('对照这份原件', 'Open this source') : t('对照原文核对该项', 'Review this item on its source') }}</button><blockquote v-for="(anchor,index) in graphInspection.sourceAnchors ?? graphInspection.node?.sourceAnchors ?? []" :key="index">{{ anchor.text }}</blockquote><article v-for="(entry,index) in graphInspection.targets ?? []" :key="index"><blockquote>{{ entry.target?.text }}</blockquote></article></template><p v-else class="source-note">{{ t('选择一个问题、方案或文件，查看完整关联与影响范围。', 'Select a question, action or file to inspect its relationships and possible impact.') }}</p></aside></div>
    </AppModal>
    <AppModal :open="historyOpen" :title="t('已保存的图谱版本', 'Saved graph revisions')" wide @close="historyOpen = false"><article v-for="revision in history" :key="revision.id" class="revision-row"><span>{{ revision.createdAt }} · {{ revision.status }} · {{ revision.sourceStale ? t('来源已变化', 'Source changed') : t('保存的来源绑定', 'Saved source bindings') }}</span><button class="btn" :disabled="busy || locked || revision.sourceStale" @click="restoreRevision(revision)">{{ t('作为新草稿核对', 'Review as a new draft') }}</button></article></AppModal>
    <AppModal :open="originalOpen" :title="t('实际原件版面', 'Actual source layout')" wide @close="originalOpen = false"><p v-if="!pdfUrl" class="review-error">{{ error || t('原件版面正在读取。若无法显示，可关闭此窗继续核对准确原文。', 'Loading the source layout. If unavailable, close this dialog and continue with the exact source text.') }}</p><button v-if="!pdfUrl" class="btn" @click="openOriginal">{{ t('重新读取原件版面', 'Retry source layout') }}</button><DraftingPdfPreview v-if="pdfUrl" :source="pdfUrl" :title="reading?.fileName ?? ''" :locale="locale as any" /></AppModal>
  </fieldset></section>
</template>

