rap;overflow-wrap:anywhere}.review-error{color:var(--red);background:var(--red-soft);padding:10px;font-size:12px}.condition-case,.target-row{padding:12px;border:1px solid var(--line);border-radius:6px;margin:10px 0}.condition-row{display:flex;flex-wrap:wrap;gap:5px;margin:10px 0}.condition-row>select{min-width:100px;max-width:100%}.split-columns{display:grid;grid-template-columns:1fr 1fr;gap:16px}.split-columns input{width:100%;margin:5px 0}.review-graph-body{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:14px;margin-top:14px}.graph-scroll{max-height:70vh;overflow:auto;border:1px solid var(--line);border-radius:8px;background:var(--surface-subtle)}.review-graph-inspector{max-height:70vh;overflow:auto;border:1px solid var(--line);border-radius:8px;padding:16px}.graph-canvas{position:relative}.graph-canvas svg{position:absolute;inset:0;pointer-events:none}.graph-canvas path{fill:none;stroke:#aebfb7;stroke-width:.9;opacity:.32}.graph-canvas path.selected{stroke:var(--orange,#d86b1f);stroke-width:1.6;opacity:1}.graph-canvas path.dim{opacity:.09}.graph-canvas path.reference,.graph-canvas path.split-origin{stroke-dasharray:5 4}.graph-canvas path.condition,.graph-canvas path.scope{stroke-dasharray:1 4;stroke:#779dbe}.graph-node{position:absolute;border:1px solid #8dc9c4;background:#e6f4f2;border-radius:5px;padding:10px;text-align:left;font:inherit;font-size:12px;line-height:1.55;overflow:hidden;cursor:pointer}.graph-node strong{display:block;font-weight:600}.graph-node.action-node{background:#fbf0e7;border-color:#e9aa7e}.graph-node.file-node{background:#edf2fa;border-color:#9abce0}.graph-node.selected{border:2px solid var(--orange,#d86b1f)}.graph-node.dim{opacity:.28}.graph-node:focus-visible{outline:2px solid var(--accent);outline-offset:2px}.graph-node small{display:block;color:var(--muted);font-size:10px}.revision-row{display:flex;justify-content:space-between;gap:12px;margin:14px 0}@media(max-width:700px){.review-graph-body{grid-template-columns:1fr}.review-graph-inspector{max-height:30vh}}@media(max-width:1100px){.review-columns{grid-template-columns:1fr}.native-source{max-height:55vh}.review-editor{max-height:none}.split-columns{grid-template-columns:1fr}}
